import{_ as u,a0 as l,w as i,s as d,I as t,x as s,a1 as n,A as e,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 Kubuntu 21.10 中升級 KDE Plasma 5.24 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kubuntu 21.10 中升級 KDE Plasma 5.24 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kubuntu 21.10 中升級 KDE Plasma 5.24 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kubuntu 21.10 中升級 KDE Plasma 5.24 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220212 How to Get KDE Plasma 5.24 in Kubuntu 21.10 Impish Indri","title":"如何在 Kubuntu 21.10 中升級 KDE Plasma 5.24","tag":"202202","desc":""},"relativePath":"202202/20220212 How to Get KDE Plasma 5.24 in Kubuntu 21.10 Impish Indri.md","filePath":"[post].md"}'),r={name:"202202/20220212 How to Get KDE Plasma 5.24 in Kubuntu 21.10 Impish Indri.md"};function b(m,a,k,h,g,K){const p=l("Link");return i(),d("div",null,[a[18]||(a[18]=t("h1",{id:"如何在-kubuntu-21-10-中升級-kde-plasma-5-24",tabindex:"-1"},[s("如何在 Kubuntu 21.10 中升級 KDE Plasma 5.24 "),t("a",{class:"header-anchor",href:"#如何在-kubuntu-21-10-中升級-kde-plasma-5-24","aria-label":"Permalink to “如何在 Kubuntu 21.10 中升級 KDE Plasma 5.24”"},"​")],-1)),a[19]||(a[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202202/17/093727qw3js653lzksscfw.jpg",alt:""})],-1)),a[20]||(a[20]=t("blockquote",null,[t("p",null,"KDE 開發人員啓用了有名的 Backports PPA，以便你在 Kubuntu 21.10 中安裝/升級到 KDE Plasma 5.24。 以下是方法。")],-1)),t("p",null,[a[1]||(a[1]=s("KDE Plasma 5.24 最近的 ",-1)),n(p,{href:"https://kde.org/announcements/plasma/5/5.24.0/"},{default:e(()=>[...a[0]||(a[0]=[s("發佈",-1)])]),_:1}),a[2]||(a[2]=s(" 帶來了令人興奮的變化。在這個新版本中，你會得到一個全新的概覽頁面，它很像 GNOME 的概覽。此外，還有嶄新的默認 Breeze 主題、性能提升、通知外觀的調整等。在我們的 [官方綜述頁面][2] 可以閲讀更多關於這些功能的信息。",-1))]),a[21]||(a[21]=o(`<p>如果你很匆忙，沒有時間閲讀文章，這裏有一組簡短的命令，可以做到這些。😃</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p>如果你運行 Kubuntu 21.10 Impish Indri，你不會馬上得到這個更新。因為 Kubuntu 21.10 Impish Indri 目前採用 KDE Plasma 5.22.5 作為穩定版本。儘管 Kubuntu 21.10 計劃在 2022 年 7 月結束生命，但你仍然可以通過 Backports PPA 安裝 KDE Plasma 5.24。</p><p>然而，請注意，你將在 2022 年 4 月的 Kubuntu 22.04 LTS 中得到 KDE Plasma 5.24，這要比 Kubuntu 21.10 的壽命結束早得多。</p><h3 id="如何在-kubuntu-21-10-中安裝-kde-plasma-5-24" tabindex="-1">如何在 Kubuntu 21.10 中安裝 KDE Plasma 5.24 <a class="header-anchor" href="#如何在-kubuntu-21-10-中安裝-kde-plasma-5-24" aria-label="Permalink to “如何在 Kubuntu 21.10 中安裝 KDE Plasma 5.24”">​</a></h3><p>下面是你如何將 Kubuntu 21.10 中現有的 KDE Plasma 更新到最新版本。</p><h4 id="如何在-kubuntu-21-10-中安裝-kde-plasma-5-24-1" tabindex="-1">如何在 Kubuntu 21.10 中安裝 KDE Plasma 5.24 <a class="header-anchor" href="#如何在-kubuntu-21-10-中安裝-kde-plasma-5-24-1" aria-label="Permalink to “如何在 Kubuntu 21.10 中安裝 KDE Plasma 5.24”">​</a></h4><p>如果你習慣使用“<ruby>發現<rt>Discover</rt></ruby>” 感到滿意，請添加 Backports PPA <code>ppa:kubuntu-ppa/backports</code> 作為軟件源並點擊更新。一旦檢索到更新的軟件包信息，就可以安裝。</p><p>我建議使用以下終端方法，以獲得更快和無錯誤的安裝。</p><p>打開 Konsole，運行以下命令來添加 backports PPA。如果你喜歡，你可以驗證你運行的 Plasma 是什麼版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backports</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/02/Add-the-PPA.jpg" alt="Add the PPA"></p><p>現在，刷新軟件包列表並驗證最新的 5.24 軟件包是否可供升級。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/02/Check-the-latest-KDE-Plasma-5.24-packages-before-upgrade.jpg" alt="Check the latest KDE Plasma 5.24 packages before upgrading"></p><p>現在運行最後的命令來啓動升級。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p>上面的命令會下載大約 270MB 以上的軟件包。升級過程大約需要 10 分鐘。命令完成後，重啓你的系統。</p><p>而你應該通過 Kubuntu 21.10 Impish Indri 獲得了全新的 KDE Plasma 5.24。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/02/KDE-Plasma-5.24-in-Kubuntu-21.10-1024x579.jpg" alt="KDE Plasma 5.24 in Kubuntu 21.10"></p><h4 id="如何在-ubuntu-21-10-中與-gnome-一起安裝-kde-plasma-5-24" tabindex="-1">如何在 Ubuntu 21.10 中與 GNOME 一起安裝 KDE Plasma 5.24 <a class="header-anchor" href="#如何在-ubuntu-21-10-中與-gnome-一起安裝-kde-plasma-5-24" aria-label="Permalink to “如何在 Ubuntu 21.10 中與 GNOME 一起安裝 KDE Plasma 5.24”">​</a></h4><p>如果你正在運行帶有默認 GNOME 的 Ubuntu 21.10 Impish Indri，你也可以體驗全新的 KDE Plasma 桌面，只需對上述命令稍作修改即可。</p><p>打開一個終端，依次運行下面的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:kubuntu-ppa/backpots</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install kubuntu-desktop</span></span></code></pre></div><p>上述命令完成後，重啓系統。在登錄頁面上，選擇 KDE Plasma 作為桌面環境。然後你就可以開始了。</p><p>這將與 GNOME 桌面一起安裝 KDE Plasma 5.24。</p><h4 id="我可以在-ubuntu-20-04-lts-中安裝-kde-plasma-5-24-嗎" tabindex="-1">我可以在 Ubuntu 20.04 LTS 中安裝 KDE Plasma 5.24 嗎？ <a class="header-anchor" href="#我可以在-ubuntu-20-04-lts-中安裝-kde-plasma-5-24-嗎" aria-label="Permalink to “我可以在 Ubuntu 20.04 LTS 中安裝 KDE Plasma 5.24 嗎？”">​</a></h4><p>Ubuntu 20.04 LTS 版有早期的 KDE Plasma 5.18、KDE Framework 5.68、KDE Applications 19.12.3。所以，在它的整個生命週期中，它不會收到最新的 KDE 更新。所以，從技術上講，你可以添加上述 PPA 並安裝 KDE Plasma 5.24。但我不建議這樣做，因為不兼容的軟件包框架可能會導致系統不穩定。</p><p>所以，建議你使用 Kubuntu 21.10 和上述的 Backports PPA 或者使用 KDE Neon 來體驗最新的 Plasma 桌面。</p><h3 id="如何卸載" tabindex="-1">如何卸載 <a class="header-anchor" href="#如何卸載" aria-label="Permalink to “如何卸載”">​</a></h3><p>在任何時候，如果你想回到 KDE Plasma 桌面的原始版本，那麼你可以安裝 <code>ppa-purge</code> 並刪除 PPA，接着刷新軟件包。</p><p>打開一個終端，依次執行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ppa-purge</span></span>
<span class="line"><span>sudo ppa-purge ppa:kubuntu-ppa/backports</span></span>
<span class="line"><span>sudo apt update</span></span></code></pre></div><p>當命令完成，重啓你的系統。</p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>我希望這個快速指南能讓你從不同的使用情況下全面升級到 KDE Plasma 5.24。希望你能在沒有任何錯誤的情況下完成升級。</p><p>請在下面的評論欄裏告訴我進展如何。</p><hr>`,37)),t("p",null,[a[4]||(a[4]=s("via: ",-1)),n(p,{href:"https://www.debugpoint.com/2022/02/kde-plasma-5-24-kubuntu-21-10/"},{default:e(()=>[...a[3]||(a[3]=[s("https://www.debugpoint.com/2022/02/kde-plasma-5-24-kubuntu-21-10/",-1)])]),_:1})]),t("p",null,[a[9]||(a[9]=s("作者：",-1)),n(p,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...a[5]||(a[5]=[s("Arindam",-1)])]),_:1}),a[10]||(a[10]=s(" 選題：",-1)),n(p,{href:"https://github.com/lujun9972"},{default:e(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 譯者：",-1)),n(p,{href:"https://github.com/geekpi"},{default:e(()=>[...a[7]||(a[7]=[s("geekpi",-1)])]),_:1}),a[12]||(a[12]=s(" 校對：",-1)),n(p,{href:"https://github.com/wxy"},{default:e(()=>[...a[8]||(a[8]=[s("wxy",-1)])]),_:1})]),t("p",null,[a[15]||(a[15]=s("本文由 ",-1)),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原創編譯，",-1)),n(p,{href:"https://linux.cn/"},{default:e(()=>[...a[14]||(a[14]=[s("Linux中國",-1)])]),_:1}),a[17]||(a[17]=s(" 榮譽推出",-1))])])}const E=u(r,[["render",b]]);export{D as __pageData,E as default};
